116	// friendlyErr 去掉内部哨兵错误（errNotFound/errConflict）的英文前缀。
117	func friendlyErr(msg string) string {
118		for _, p := range []string{"not found: ", "conflict: "} {
119			if strings.HasPrefix(msg, p) {
120				return msg[len(p):]
121			}
122		}
123		return msg
124	}
