126	type usageError struct{ msg string }
127	
128	func (e *usageError) Error() string { return e.msg }
129	
130	// newFlagSet 为子命令准备参数解析器：--help/-h 输出帮助并返回 flag.ErrHelp，
131	// 其余参数错误转成 *usageError（退出码 2）。
132	func newFlagSet(name string, opts *cmdOptions) *flag.FlagSet {
133		fs := flag.NewFlagSet(name, flag.ContinueOnError)
134		fs.SetOutput(os.Stdout)
135		fs.Usage = func() {
136			fmt.Fprintf(os.Stdout, "用法: caretrack %s [参数]\n\n", name)
137			fs.PrintDefaults()
138		}
139		fs.StringVar(&opts.dataDir, "data-dir", ".caretrack", "本地数据目录")
140		return fs
141	}
