// parseTicketSeq 解析 T 加补零正整数序号形式的工单编号，返回序号。
// 编号必须与 fmt.Sprintf("T%04d", n)（n ≥ 1）完全一致，否则视为非法。
func parseTicketSeq(id string) (int, bool) {
	if !strings.HasPrefix(id, "T") {
		return 0, false
	}
	n, err := strconv.Atoi(id[1:])
	if err != nil || n < 1 {
		return 0, false
	}
	if fmt.Sprintf("T%04d", n) != id {
		return 0, false
	}
	return n, true
}

