		appendTo(m, "events", map[string]any{
			"seq": math.MaxInt, "asset_id": "EQ-1", "ticket_id": "T0001",
			"kind": "关闭", "content": "已修复", "time": "2026-10-01T11:00:00Z",
		})
	})
	s, err := openStore(dir)
	if err != nil {
