			var out, errBuf bytes.Buffer
			if code := run([]string{"list", "--data-dir", dir}, &out, &errBuf); code != 1 {
				t.Fatalf("矛盾台账上 list 退出码 = %d，应为 1（%s）", code, errBuf.String())
